import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"projects/steve/introduction.md","filePath":"projects/steve/introduction.md","lastUpdated":1787695050000}'),n={name:"projects/steve/introduction.md"};function s(i,e,l,d,u,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#invite">Invite</a><ul><li><a href="#enable-server-querying">Enable server querying</a></li><li><a href="#use-the-setup-commands">Use the Setup commands</a></li><li><a href="#finish">Finish</a></li></ul></li><li><a href="#self-host">Self Host</a></li></ul></nav><h1 align="center">Steve.</h1><h3 align="center">A Minecraft Server Status Panel</h3><p align="center"><a href="https://github.com/nathanlytang/Steve" alt="Version"><img src="https://img.shields.io/github/package-json/v/nathanlytang/Steve"></a><a href="https://github.com/nathanlytang/Steve" alt="License"><img src="https://img.shields.io/github/license/nathanlytang/Steve"></a><a href="https://github.com/nathanlytang/Steve" alt="Language"><img src="https://img.shields.io/github/languages/top/nathanlytang/Steve"></a></p><hr><p><a href="https://github.com/nathanlytang/steve/" target="_blank" rel="noreferrer">Steve</a> is a Discord bot that tracks your Minecraft servers. Built in the Node.js environment and the <a href="https://discord.js.org/#/" target="_blank" rel="noreferrer">discord.js</a> library, Steve aims to provide an easily accessible and well displayed status panel for your server.</p><h2 id="invite" tabindex="-1">Invite <a class="header-anchor" href="#invite" aria-label="Permalink to &quot;Invite&quot;">​</a></h2><p>Invite Steve to your Discord server <a href="https://discord.com/api/oauth2/authorize?client_id=773117222380896276&amp;permissions=2147502080&amp;scope=applications.commands%20bot" target="_blank" rel="noreferrer">here</a>. Run <code>/setup</code> and follow the setup instructions.</p><h3 id="enable-server-querying" tabindex="-1">Enable server querying <a class="header-anchor" href="#enable-server-querying" aria-label="Permalink to &quot;Enable server querying&quot;">​</a></h3><h5 id="vanilla-servers" tabindex="-1">Vanilla Servers <a class="header-anchor" href="#vanilla-servers" aria-label="Permalink to &quot;Vanilla Servers&quot;">​</a></h5><ul><li>In your <code>server.properties file</code>, set <code>enable-query</code> to <code>true</code>.</li><li>In <code>server.properties</code>, ensure <code>query.port</code> is the same as <code>server.port</code>.</li><li>Ensure the query port is port forwarded if not using server port.</li><li>Save and restart the server.</li></ul><h5 id="bungeecord-servers" tabindex="-1">Bungeecord Servers <a class="header-anchor" href="#bungeecord-servers" aria-label="Permalink to &quot;Bungeecord Servers&quot;">​</a></h5><ul><li>In <code>config.yml</code>, set <code>query_enabled</code> to true.</li><li>In <code>config.yml</code>, ensure <code>query_port</code> is the same as server port (<code>host</code> port)</li><li>Ensure the query port is port forwarded if not using server port.</li><li>Save and restart the proxy.</li></ul><h5 id="unable-to-use-query" tabindex="-1">Unable to use Query <a class="header-anchor" href="#unable-to-use-query" aria-label="Permalink to &quot;Unable to use Query&quot;">​</a></h5><p>If you cannot enable query on your server, run <code>/setup query &lt;True|False</code> to enable or disable querying. When query is disabled, Steve will instead use server pinging. Note that this may break some functionality (Player list will not be shown on Bungeecord servers).</p><h3 id="use-the-setup-commands" tabindex="-1">Use the Setup commands <a class="header-anchor" href="#use-the-setup-commands" aria-label="Permalink to &quot;Use the Setup commands&quot;">​</a></h3><p><code>/setup ip &lt;SERVER IP&gt;</code> | Set the server IP (URL also accepted)</p><p><code>/setup port &lt;SERVER PORT&gt;</code> | Set the server port (Default 25565)</p><p><code>/setup name &lt;SERVER NAME&gt;</code> | Give your server a name</p><p><code>/setup footer &lt;FOOTER MESSAGE&gt;</code> | Set a footer message for your status panel</p><h3 id="finish" tabindex="-1">Finish <a class="header-anchor" href="#finish" aria-label="Permalink to &quot;Finish&quot;">​</a></h3><p>Setup is complete! Run <code>-mc status</code> to display the server status panel. More commands can be found <a href="https://github.com/nathanlytang/Steve#commands" target="_blank" rel="noreferrer">here</a> or by typing <code>-mc help</code> in your Discord server.</p><h2 id="self-host" tabindex="-1">Self Host <a class="header-anchor" href="#self-host" aria-label="Permalink to &quot;Self Host&quot;">​</a></h2><p>If you would like to host the bot yourself, instructions on how to do so can be found <a href="./getting_started">here</a>.</p><p>Direct Links:</p><ul><li><a href="./getting_started">Getting Started</a></li><li><a href="./db_setup">Database Setup</a></li><li><a href="./additional_configuration">Additional Configuration</a></li></ul>',27)])])}const f=t(n,[["render",s]]);export{p as __pageData,f as default};
